"""Add the first original official-pattern prediction batch to the bank.

The batch is deliberately small and daily-only.  It is generated from a
fixed specification so the operation is reproducible and safe to repeat.
"""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BANK = ROOT / "bank"
BATCH = "official-pattern-v1"


def option_reasons(texts, reasons):
    return {key: value for key, value in zip("ABCD", reasons)}


def item(*, ident, grade, subject, family, competency, module, cognitive,
         difficulty, kind, stem, options, answer, explanation, framework,
         subcompetency, indicator, stimulus_kind, verification=None,
         stimulus_id=None):
    row = {
        "id": ident,
        "version": 1,
        "grade": grade,
        "subject": subject,
        "family_id": family,
        "competency": competency,
        "module_id": module,
        "cognitive_level": cognitive,
        "difficulty_editorial": difficulty,
        "difficulty_calibrated": False,
        "type": kind,
        "stem": stem,
        "stimulus_id": stimulus_id,
        "options": [{"id": key, "text": text} for key, text in options],
        "category_labels": ["Benar", "Salah"] if kind == "PGK_CATEGORY" else None,
        "answer": answer,
        "explanation": explanation,
        "source": {"kind": "original", "exam_year": None, "framework_ref": framework},
        "review": {
            "status": "prediction_editorial_pending",
            "human_review_required": True,
            "independent_mitsuko_review": "pending",
        },
        "pool": "pilot_daily",
        "ranked_eligible": False,
        "prediction_batch": BATCH,
        "source_basis": "official-framework-pattern",
        "provenance": "original",
        "subcompetency": subcompetency,
        "indicator": indicator,
        "stimulus_kind": stimulus_kind,
    }
    if verification is not None:
        row["verification"] = verification
    return row


def math_explanation(concept, steps, reasons, next_action="Coba jelaskan kembali alasanmu, lalu periksa hasilnya."):
    return {
        "concept": concept,
        "steps": steps,
        "option_reasons": option_reasons(None, reasons),
        "evidence": [],
        "next_action": next_action,
    }


def reading_explanation(concept, steps, reasons, evidence):
    return {
        "concept": concept,
        "steps": steps,
        "option_reasons": option_reasons(None, reasons),
        "evidence": evidence,
        "next_action": "Tandai bagian teks yang menjadi bukti sebelum menjawab soal berikutnya.",
    }


def passage(ident, grade, genre, title, text):
    return {
        "id": ident,
        "grade": grade,
        "genre": genre,
        "title": title,
        "source_kind": "original",
        "text": text,
        "prediction_batch": BATCH,
        "source_basis": "official-framework-pattern",
        "provenance": "original",
    }


