def main():
    questions_path = BANK / "questions.json"
    passages_path = BANK / "passages.json"
    questions = json.loads(questions_path.read_text(encoding="utf-8"))
    passages = json.loads(passages_path.read_text(encoding="utf-8"))
    if any(q.get("prediction_batch") == BATCH for q in questions) or any(p.get("prediction_batch") == BATCH for p in passages):
        print(f"Batch {BATCH} sudah ada; tidak ada perubahan.")
        return
    new_questions, new_passages = build()
    if len(new_questions) != 40:
        raise SystemExit(f"Expected 40 generated questions, got {len(new_questions)}")
    existing_ids = {q["id"] for q in questions}
    existing_families = {q["family_id"] for q in questions}
    existing_stimuli = {p["id"] for p in passages}
    new_ids = {q["id"] for q in new_questions}
    new_families = {q["family_id"] for q in new_questions}
    new_stimuli = {p["id"] for p in new_passages}
    if len(new_ids) != 40 or new_ids & existing_ids:
        raise SystemExit("Question ID collision or duplicate in generated batch")
    if len(new_families) != 40 or new_families & existing_families:
        raise SystemExit("Family ID collision or duplicate in generated batch")
    if len(new_stimuli) != 4 or new_stimuli & existing_stimuli:
        raise SystemExit("Stimulus ID collision or duplicate in generated batch")
    if any(q["prediction_batch"] != BATCH for q in new_questions):
        raise SystemExit("Generated question has incorrect prediction_batch")
    if any(q["pool"] != "pilot_daily" or q["ranked_eligible"] is not False for q in new_questions):
        raise SystemExit("Prediction batch must remain daily-only")
    questions_path.write_text(json.dumps(questions + new_questions, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    passages_path.write_text(json.dumps(passages + new_passages, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"batch": BATCH, "questions_added": 40, "passages_added": 4}, ensure_ascii=False))


if __name__ == "__main__":
    main()
